/**
 * ChatGPT web (`unauth-mweb`) client.
 *
 * The observed turn is a three-step dance (DOCS.md):
 *
 *   1. `conversation/prepare`        → conduit_token
 *   2. sentinel `prepare`/`finalize` → anti-abuse requirements
 *   3. `conversation/updates`        → NDJSON stream (control/content/state/end)
 *
 * Step 2's payload (`p`) and the resulting `chatRequirementsToken`,
 * `proofToken` and `turnstileToken` are generated by obfuscated browser code
 * that was not reverse-engineered. The client therefore exposes them as an
 * explicit hook (`getRequirements`) plus static options: everything else —
 * preparation, form encoding, stream decoding — is implemented.
 */

import { randomUUID } from "node:crypto";

import {
  ApiError,
  ERROR_CODES,
  classifyError,
  truncate,
  withRetry,
} from "../../../lib/errors.js";
import { CookieJar, encodeForm, mergeHeaders, readTextBounded, requestResponse, toCookieJar } from "../../../lib/http.js";
import { iterateFrames } from "../../../lib/stream.js";
import {
  BASE_URL,
  CONVERSATION_RETRY_OWNER,
  DEFAULT_CLIENT_CONTEXT,
  DEFAULT_HEADERS,
  DEFAULT_MAX_RESPONSE_BYTES,
  DEFAULT_STREAM_IDLE_TIMEOUT_MS,
  DEFAULT_TIMEOUT_MS,
  INITIAL_CONVERSATION_STATE,
  PATHS,
  PROVIDER,
} from "./constants.js";

function asJsonString(value, fallback) {
  if (value == null) return JSON.stringify(fallback);
  if (typeof value === "string") return value;
  return JSON.stringify(value);
}

function parseJsonMaybe(value) {
  if (typeof value !== "string") return value ?? null;
  try {
    return JSON.parse(value);
  } catch (_) {
    return null;
  }
}

/** Pull assistant text out of a `content` frame (markdown or DIL). */
export function contentText(frame) {
  if (!frame || frame.type !== "content") return "";
  const markdown = typeof frame.markdown === "string" ? frame.markdown : "";
  if (markdown) return markdown;
  const fallback = frame.dil && typeof frame.dil.fallbackMarkdown === "string" ? frame.dil.fallbackMarkdown : "";
  return fallback || "";
}

export class ChatGPTClient {
  constructor(opts = {}) {
    if (typeof opts === "string") opts = { prompt: opts };
    this.fetchImpl = opts.fetchImpl || globalThis.fetch;
    this.baseUrl = (opts.baseUrl || BASE_URL).replace(/\/+$/, "");
    this.headers = mergeHeaders(DEFAULT_HEADERS, opts.headers);
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.streamIdleTimeoutMs = opts.streamIdleTimeoutMs ?? DEFAULT_STREAM_IDLE_TIMEOUT_MS;
    this.retries = Math.max(0, Number(opts.retries ?? 0) || 0);
    this.retryDelayMs = opts.retryDelayMs;
    this.maxResponseBytes = opts.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;
    this.cookieJar = toCookieJar(opts.cookieJar ?? opts.cookies);
    this.sessionId = opts.sessionId || randomUUID();
    this.timezone = opts.timezone || "UTC";
    this.timezoneOffsetMinutes = opts.timezoneOffsetMinutes ?? 0;
    this.sentinelP = opts.sentinelP || null;
    this.tokens = { ...(opts.tokens || {}) };
    this.getRequirements = typeof opts.getRequirements === "function" ? opts.getRequirements : null;
    this.clientContext = { ...DEFAULT_CLIENT_CONTEXT, ...(opts.clientContext || {}) };
    this.lastPrepare = null;
  }

  url(path) {
    return `${this.baseUrl}${path}`;
  }

  #headers(extra = {}) {
    const cookie = this.cookieJar.toString();
    return mergeHeaders(
      { ...this.headers, "oai-session-id": this.sessionId },
      cookie ? { cookie } : null,
      extra
    );
  }

  #ingest(res) {
    this.cookieJar.ingestResponse(res);
    return res;
  }

  /** Exchange a prompt-era `p` blob for a sentinel `prepare_token`. */
  async prepareSentinel({ p = this.sentinelP, signal } = {}) {
    if (!p) {
      throw new ApiError(
        "sentinel prepare needs the obfuscated `p` payload (option sentinelP, CLI --sentinel-p)",
        { provider: PROVIDER, code: ERROR_CODES.INVALID_INPUT }
      );
    }
    const { json } = await this.#postJson(PATHS.sentinelPrepare, { p }, { signal, retry: true });
    return json;
  }

  async finalizeSentinel({ prepareToken, signal } = {}) {
    if (!prepareToken) {
      throw new ApiError("finalize needs prepare_token", {
        provider: PROVIDER,
        code: ERROR_CODES.INVALID_INPUT,
      });
    }
    const { json } = await this.#postJson(PATHS.sentinelFinalize, { prepare_token: prepareToken }, { signal });
    return json;
  }

  /** `conversation/prepare` — returns the ES256 conduit token and raw response. */
  async prepareConversation({ conversationState = INITIAL_CONVERSATION_STATE, signal } = {}) {
    const form = encodeForm({
      conversationRetryOwner: JSON.stringify(CONVERSATION_RETRY_OWNER),
      conversationState: asJsonString(conversationState, INITIAL_CONVERSATION_STATE),
      clientContextualInfo: JSON.stringify(this.clientContext),
      timezone: this.timezone,
      timezoneOffsetMinutes: this.timezoneOffsetMinutes,
    });
    const { res } = await requestResponse(
      this.url(PATHS.conversationPrepare),
      {
        method: "POST",
        headers: this.#headers({
          "content-type": "application/x-www-form-urlencoded",
          accept: "application/json",
        }),
        body: form,
        signal,
      },
      {
        fetchImpl: this.fetchImpl,
        timeoutMs: this.timeoutMs,
        maxResponseBytes: this.maxResponseBytes,
        provider: PROVIDER,
      }
    );
    this.#ingest(res);
    const text = await readTextBounded(res, this.maxResponseBytes);
    let json;
    try {
      json = text ? JSON.parse(text) : null;
    } catch (e) {
      throw new ApiError("conversation/prepare did not return JSON", {
        provider: PROVIDER,
        code: ERROR_CODES.PARSE_ERROR,
        details: truncate(text, 400),
        cause: e,
      });
    }
    this.lastPrepare = json;
    return json;
  }

  async #postJson(path, body, { signal, retry = false } = {}) {
    const send = () =>
      requestResponse(
        this.url(path),
        {
          method: "POST",
          headers: this.#headers({ "content-type": "application/json", accept: "application/json" }),
          body: JSON.stringify(body),
          signal,
        },
        {
          fetchImpl: this.fetchImpl,
          timeoutMs: this.timeoutMs,
          maxResponseBytes: this.maxResponseBytes,
          provider: PROVIDER,
        }
      );
    const { res } = retry
      ? await withRetry(send, {
          retries: this.retries,
          signal,
          retryDelayMs: this.retryDelayMs,
          context: { provider: PROVIDER },
        })
      : await send();
    this.#ingest(res);
    const text = await readTextBounded(res, this.maxResponseBytes);
    return { res, json: parseJsonMaybe(text) ?? text };
  }

  /**
   * Resolve the anti-abuse tokens: explicit options win, then the hook.
   * Returns `{}` when nothing is available (caller decides whether to fail).
   */
  async resolveRequirements(context) {
    const explicit = {
      chatRequirementsToken: this.tokens.chatRequirementsToken,
      proofToken: this.tokens.proofToken,
      turnstileToken: this.tokens.turnstileToken,
      ...(context.tokens || {}),
    };
    const missing = ["chatRequirementsToken", "proofToken", "turnstileToken"].filter(
      (k) => !explicit[k]
    );
    if (!missing.length || !this.getRequirements) return explicit;

    const supplied = await this.getRequirements({ ...context, missing, client: this });
    if (!supplied || typeof supplied !== "object") return explicit;
    const merged = { ...explicit };
    for (const key of ["chatRequirementsToken", "proofToken", "turnstileToken"]) {
      if (!merged[key] && supplied[key]) merged[key] = supplied[key];
    }
    if (supplied.tokens && typeof supplied.tokens === "object") {
      Object.assign(merged, supplied.tokens);
    }
    return merged;
  }

  #submitForm({ prompt, requirements, conversationState, operationId, assistantMessageId, userMessageId }) {
    return encodeForm({
      prompt,
      chatRequirementsToken: requirements.chatRequirementsToken || "",
      proofToken: requirements.proofToken || "",
      turnstileToken: requirements.turnstileToken || "",
      "oai-session-id": this.sessionId,
      assistantMessageId,
      userMessageId,
      conversationState: asJsonString(conversationState, INITIAL_CONVERSATION_STATE),
      conversationRetryOwner: JSON.stringify(CONVERSATION_RETRY_OWNER),
      clientContextualInfo: JSON.stringify(this.clientContext),
      timezone: this.timezone,
      timezoneOffsetMinutes: this.timezoneOffsetMinutes,
      imageAttachments: "[]",
      pendingImageUploads: "[]",
      imageSaveData: "off",
      imageEffectiveType: "4g",
      messageMetadata: "",
      workOrigin: "",
      workModel: "",
      workEffort: "",
      workTier: "",
      timingToken: "[1,null]",
      telemetryToken: "",
      ...(requirements.extraFields || {}),
    });
  }

  /**
   * Submit a turn and consume the NDJSON stream.
   * Emits `control`, `state`, `text_delta`, `text_replace`, `end`.
   */
  async *streamChat(opts = {}) {
    const prompt = opts.prompt;
    if (!prompt || !String(prompt).trim()) {
      throw new ApiError("prompt is required", { provider: PROVIDER, code: ERROR_CODES.INVALID_INPUT });
    }
    const signal = opts.signal;

    let prepare = this.lastPrepare;
    if (!prepare && opts.prepare !== false) {
      try {
        prepare = await this.prepareConversation({ conversationState: opts.conversationState, signal });
        opts.onEvent?.({ type: "prepare", conduitToken: prepare?.conduit_token || null });
      } catch (e) {
        if (opts.requirePrepare !== false) throw classifyError(e, { provider: PROVIDER });
        opts.onEvent?.({ type: "warning", message: `conversation/prepare failed: ${e.message}` });
      }
    }

    let prepareToken = opts.prepareToken || null;
    if (!prepareToken && this.sentinelP) {
      const sentinel = await this.prepareSentinel({ signal });
      prepareToken = sentinel?.prepare_token || null;
      if (prepareToken && opts.finalize !== false) {
        await this.finalizeSentinel({ prepareToken, signal });
      }
      opts.onEvent?.({ type: "sentinel", persona: sentinel?.persona || null, prepared: !!prepareToken });
    }

    const operationId = opts.operationId || randomUUID();
    const assistantMessageId = opts.assistantMessageId || `pending-${randomUUID()}`;
    const userMessageId = opts.userMessageId || randomUUID();

    const requirements = await this.resolveRequirements({
      prompt,
      sessionId: this.sessionId,
      operationId,
      conversationPrepare: prepare,
      prepareToken,
      tokens: opts.tokens,
    });
    const missing = ["chatRequirementsToken", "proofToken", "turnstileToken"].filter((k) => !requirements[k]);
    if (missing.length && opts.allowMissingTokens !== true) {
      throw new ApiError(
        `missing anti-abuse token(s): ${missing.join(", ")} — supply them via the getRequirements hook or tokens option`,
        {
          provider: PROVIDER,
          code: ERROR_CODES.INVALID_INPUT,
          hint: "the sentinel proof/turnstile generation is browser-only; capture fresh tokens from a real session",
        }
      );
    }

    const form = this.#submitForm({
      prompt,
      requirements,
      conversationState: opts.conversationState,
      operationId,
      assistantMessageId,
      userMessageId,
    });

    const url =
      `${this.url(PATHS.conversationUpdates)}?lightweight_authenticated=0&operationId=${encodeURIComponent(
        operationId
      )}`;
    const { res, headers } = await requestResponse(
      url,
      {
        method: "POST",
        headers: this.#headers({
          "content-type": "application/x-www-form-urlencoded",
          accept: "application/vnd.openai.conversation-source+ndjson",
        }),
        body: form,
        signal,
      },
      {
        fetchImpl: this.fetchImpl,
        timeoutMs: this.timeoutMs,
        maxResponseBytes: this.maxResponseBytes,
        provider: PROVIDER,
        hint: "submit rejected — the anti-abuse tokens are probably stale or bound to another session",
      }
    );
    this.#ingest(res);

    const contentType = String(headers["content-type"] || "");
    const perMessage = new Map();
    let frames = 0;

    for await (const frame of iterateFrames(res, {
      idleTimeoutMs: this.streamIdleTimeoutMs,
      onMalformed: opts.onMalformed,
    })) {
      if (frame.json == null) continue;
      frames += 1;
      const payload = frame.json;
      opts.onRawFrame?.(payload);

      switch (payload.type) {
        case "control": {
          const detail = payload.detail || {};
          yield {
            type: "control",
            kind: detail.kind || null,
            conversationId: detail.conversationId || null,
            messageId: detail.messageId || null,
            operationId: detail.operationId || operationId,
            detail,
            stopConduitToken: payload.stopConduitToken || null,
            resumeToken: detail.resumeToken || null,
            canonicalPath: detail.canonicalPath || null,
          };
          break;
        }
        case "state": {
          yield {
            type: "state",
            conversationState: parseJsonMaybe(payload.conversationState),
            safety: payload.safety || null,
          };
          break;
        }
        case "content": {
          const messageId = payload.messageId || "assistant";
          const text = contentText(payload);
          const previous = perMessage.get(messageId) || "";
          let next = previous;
          if (payload.mode === "replace") next = text;
          else if (payload.mode === "append") next = previous + text;
          else next = text || previous;
          perMessage.set(messageId, next);

          if (next !== previous) {
            if (payload.mode === "replace") {
              yield { type: "text_replace", text: next, messageId, revision: payload.revision ?? null };
            } else if (next.startsWith(previous)) {
              const delta = next.slice(previous.length);
              if (delta) yield { type: "text_delta", delta, messageId, revision: payload.revision ?? null };
            } else {
              yield { type: "text_replace", text: next, messageId, revision: payload.revision ?? null };
            }
          }
          break;
        }
        case "shared": {
          yield { type: "shared", html: payload.html || "" };
          break;
        }
        case "end": {
          yield { type: "end" };
          break;
        }
        default: {
          yield { type: "frame", frame: payload };
          break;
        }
      }
    }

    if (frames === 0) {
      throw new ApiError(
        contentType.includes("ndjson")
          ? "stream closed without any frames"
          : `unexpected response content-type: ${contentType || "(none)"}`,
        { provider: PROVIDER, code: ERROR_CODES.STREAM_ERROR, retryable: true }
      );
    }
  }

  async chat(opts = {}) {
    const answerByMessage = new Map();
    const frames = [];
    const events = [];
    let conversationId = opts.conversationId || null;
    let conversationState = opts.conversationState || null;
    let sessionId = opts.sessionId || this.sessionId;
    let partial = false;
    const startedAt = Date.now();

    const answer = () => Array.from(answerByMessage.values()).join("");

    try {
      for await (const event of this.streamChat(opts)) {
        frames.push(event);
        opts.onEvent?.(event);
        switch (event.type) {
          case "control":
            if (event.kind === "conversation-id" && event.conversationId) conversationId = event.conversationId;
            break;
          case "state":
            if (event.conversationState) conversationState = event.conversationState;
            break;
          case "text_delta":
            answerByMessage.set(event.messageId, (answerByMessage.get(event.messageId) || "") + event.delta);
            break;
          case "text_replace":
            answerByMessage.set(event.messageId, event.text);
            break;
          default:
            break;
        }
      }
    } catch (e) {
      partial = answer().length > 0;
      const error = classifyError(e, { provider: PROVIDER });
      if (opts.allowPartial === false) answerByMessage.clear();
      return {
        ok: false,
        provider: PROVIDER,
        answer: answer(),
        conversationId,
        conversationState,
        sessionId,
        operationId: opts.operationId || null,
        error: error.message,
        errorInfo: error.toJSON(),
        partial,
        frames,
        warnings: partial ? ["stream ended early; the answer is partial"] : [],
        meta: { durationMs: Date.now() - startedAt },
      };
    }

    return {
      ok: true,
      provider: PROVIDER,
      answer: answer(),
      conversationId,
      conversationState,
      sessionId,
      operationId: opts.operationId || null,
      error: null,
      errorInfo: null,
      partial: false,
      frames,
      warnings: [],
      meta: { durationMs: Date.now() - startedAt },
    };
  }
}

export async function chatGPTChat(opts = {}) {
  const client = opts.client instanceof ChatGPTClient ? opts.client : new ChatGPTClient(opts);
  return client.chat(opts);
}

export async function chatGPTChatOrThrow(opts = {}) {
  const result = await chatGPTChat(opts);
  if (!result.ok) throw Object.assign(new Error(result.error), result.errorInfo || {});
  return result;
}

export { CookieJar };
